import{_ as o,a as t,b as a,c as n,d as i}from"./chunks/7b481882d0158c964c66.Ck8ucOyy.js";import{_ as r,o as s,c as l,a6 as h}from"./chunks/framework.CnPv4DE1.js";const b=JSON.parse('{"title":"You’re Supposed To Feel Overwhelmed (How To Learn Any Skill FAST)","description":"","frontmatter":{"title":"You’re Supposed To Feel Overwhelmed (How To Learn Any Skill FAST)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/i-discovered-a-way-to-learn-10x-faster-reality-metabolism-universal-thinking.md","filePath":"en/letters/i-discovered-a-way-to-learn-10x-faster-reality-metabolism-universal-thinking.md"}'),u={name:"en/letters/i-discovered-a-way-to-learn-10x-faster-reality-metabolism-universal-thinking.md"};function p(d,e,c,m,y,f){return s(),l("div",null,[...e[0]||(e[0]=[h('<h1 id="you-re-supposed-to-feel-overwhelmed-how-to-learn-any-skill-fast" tabindex="-1">You’re Supposed To Feel Overwhelmed (How To Learn Any Skill FAST) <a class="header-anchor" href="#you-re-supposed-to-feel-overwhelmed-how-to-learn-any-skill-fast" aria-label="Permalink to &quot;You’re Supposed To Feel Overwhelmed (How To Learn Any Skill FAST)&quot;">​</a></h1><p>Dan Koe · 2024-02-02 · <a href="https://thedankoe.com/letters/i-discovered-a-way-to-learn-10x-faster-reality-metabolism-universal-thinking/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/i-discovered-a-way-to-learn-10x-faster-reality-metabolism-universal-thinking">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/KrCzMfvSDv0?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+o+'" alt=""></p><p>People think they aren’t supposed to feel overwhelmed.</p><ul><li>You feel slight discomfort</li><li>Your mind hates it</li><li>You haven’t trained your awareness</li><li>You snap back to comfort and pleasure in an instant</li><li>You close yourself off to expansion, growth, and understanding</li></ul><p>When I attempt to learn something new, none of it makes sense.</p><p>I feel overwhelmed and like I’m regressing instead of progressing.</p><p>In reality, I’m priming my mind for pattern recognition. My subconscious mind is soaking up information like a sponge as I expose myself to the new material.</p><p>Slowly, then all at once, it makes sense.</p><p>The “click.”</p><p>The “aha! moment.”</p><p>The avalanche called insight crashes into your psyche.</p><p>But only if you stay with the discomfort, feel into it, and allow your supercomputer of a mind to piece everything together.</p><p>Nothing happens, then everything happens.</p><p>If you want the full philosophy and steps to turning what you learn into a meaningful career, grab <a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">The Art of Focus</a> on Amazon.</p><h2 id="reality-metabolism-–-the-cause-of-mental-obesity" tabindex="-1">Reality Metabolism – The Cause Of Mental Obesity <a class="header-anchor" href="#reality-metabolism-–-the-cause-of-mental-obesity" aria-label="Permalink to &quot;Reality Metabolism – The Cause Of Mental Obesity&quot;">​</a></h2><p>You feel overwhelmed because you can’t digest reality fast enough.</p><p>You can’t deal with the overwhelm because it consumes your attention.</p><p>All you can focus on are the negative thoughts flooding your mind about how it won’t work, how you will fail, and how you could be doing something better with your time.</p><p>In bodybuilding, you build muscle by increasing your food intake, stressing your body with resistance training, and getting ample rest for recovery.</p><p>You will gain a bit of fat along the way, but this is inevitable if you want to see noticeable results.</p><p>In mindbuilding, you build knowledge by increasing your information intake, stressing your mind with challenging concepts, and taking breaks so your subconscious can munch on complex problems.</p><p>When you learn something new, it’s new.</p><p>Your mind hasn’t developed the systems that make it seamless.</p><p>You didn’t always know how to walk, talk, eat, drive, text, make your bed, throw a football, and whatever else you do for work, rest, and play.</p><p>You trained your mental metabolism to digest that aspect of reality with ease. You’ve built the mental muscle to lift the emotional labor that comes with doing those things.</p><p>The difference between then and now is the limits you’ve adopted as a part of your identity.</p><p>Your aged mind, when not kept in check with mindfulness, will cower at the first hint of discomfort.</p><p>And when you listen and obey the mind that doesn’t want what’s best for you, that becomes your default state. You become a robot self-programmed to avoid any pain, even when that pain is what brings meaning, fulfillment, and purpose to your life.</p><h3 id="live-at-the-edge-of-your-abilities" tabindex="-1">Live At The Edge Of Your Abilities <a class="header-anchor" href="#live-at-the-edge-of-your-abilities" aria-label="Permalink to &quot;Live At The Edge Of Your Abilities&quot;">​</a></h3><p>If you consume too much and create too little, your mind gets fat.</p><p>If you create too much and consume too little, your mind gets skinny.</p><p>We want neither.</p><p>When the flow of information is maximized in your life through the balance of consumption and creation, you will encounter meaningful events.</p><p>You will <em>feel</em> a deep sense of excitement for the future, fulfillment in the present, and gratitude for the past.</p><p>These feelings should be seen as an opportunity to document the important parts of your life that you can share with others.</p><p>When you read a good book and stumble across a lesson that sparks excitement, write it down.</p><p>When you feel fulfilled in the present because of the progress you are making, write it down.</p><p>When you feel grateful that your past has led you to this moment, despite your mistakes, write it down (in something like <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>).</p><p>As your notes of signal grow, you have data from which you can replicate those experiences.</p><p>You can condition your mind to occupy these states of consciousness as a baseline.</p><p>Your quality of life increases to a point of high stability.</p><h2 id="universal-thinking-–-the-solution-to-most-of-your-problems" tabindex="-1">Universal Thinking – The Solution To Most Of Your Problems <a class="header-anchor" href="#universal-thinking-–-the-solution-to-most-of-your-problems" aria-label="Permalink to &quot;Universal Thinking – The Solution To Most Of Your Problems&quot;">​</a></h2><p>You feel bad because your future self is watching your every move, and they don’t like what they see.</p><p>The solution to most of your problems:</p><p>Zoom out. Adopt the perspective of your ideal self. Break out of the narrow focus that traps you in a chaotic loop of negative thoughts.</p><p>Understand where you are, choose where you want to be, and bridge the gap with education &amp; execution.</p><p>Most people live in a state of closed-mindedness.</p><p>They fall victim to the anxiety, overwhelm, and stress that prevents them from seeing beyond their problems (so they can solve them).</p><p>People focus on the bad lyric instead of the good song.</p><p>People focus on the ugly pixel instead of the beautiful image.</p><p>You are missing the context of the situation and misinterpreting it, so you remain stuck and unable to learn.</p><p>You must train your ability to zoom out, adopt a higher perspective, and perceive situations as advantageous toward your end goal.</p><p>Form this habit:</p><p>When you sense overwhelm, pause and break the reaction cycle.</p><p>Move up the perspective ladder by opening your mind:</p><p><strong>1) Your current perspective</strong> – take inventory of your current situation.</p><p><strong>2) The perspective of your ideal self</strong> – what would the highest version of yourself do?</p><p><strong>3) The perspective of the Universe</strong> – beyond all limits, most of our worries are irrational and meaningless from the highest perspective.</p><p>These 3 stages are represented by the FOCI symbol on my book, <a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">The Art of Focus</a>.</p><p><img src="'+t+'" alt=""></p><p>When you zoom out far enough, only then can you discover potentials, connections, directions, and creative ideas that allow you to learn more than what you know.</p><p>Universal Thinking is the state of mind from which you can note patterns and understand topics from the big picture.</p><p>One can note the vast similarities between bodybuilding, mindbuilding, and businessbuilding – like progressive overload, time under tension, and proper nutrition – enhancing the results from each.</p><p>On a Universal level, you can note the birth and death of muscle, ideas, and products – helping you live at peace with the flow of your body, mind, and business – or make a decision that leads to exponential growth.</p><h2 id="how-to-learn-10x-faster" tabindex="-1">How To Learn 10x Faster <a class="header-anchor" href="#how-to-learn-10x-faster" aria-label="Permalink to &quot;How To Learn 10x Faster&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>When you learn how to learn, you can achieve 5 years of results in 6 months.</p><p>Let’s take everything we’ve learned above and ground it with practical steps.</p><h3 id="_1-create-a-clarity-catalyst" tabindex="-1">1) Create A Clarity Catalyst <a class="header-anchor" href="#_1-create-a-clarity-catalyst" aria-label="Permalink to &quot;1) Create A Clarity Catalyst&quot;">​</a></h3><p>There were a few moments in my life when I made giant leaps in learning, understanding, and progress:</p><ul><li>Writing my book</li><li>Building my products</li><li>Writing these newsletters</li></ul><p>What do they all have in common?</p><p>I treat them as a project.</p><p>A project has:</p><ul><li>An outline so you can note ideas to fill in that outline from everyday life.</li><li>Milestones so you have direction and clarity on your next steps.</li><li>A real-world deadline that forces you to act, or else your survival takes a hit.</li><li>Experimentation, trial, and error so you can turn failures into lessons.</li></ul><p>This presents a perfect environment for the flow state.</p><p>There is pattern recognition for novelty and dopamine, clarity from milestones, challenge from deadlines, and feedback from reality.</p><p>Determine what you want to learn.</p><p>Create a real-world project that you will publish for others to see.</p><p>If you don’t know what project to create, see what others have done.</p><p>If you want to learn Photoshop, your project will be anything from a graphic to a digital art scene.</p><p>If you want to learn how to bodybuild, your project is your body, nutrition regimen, and training program.</p><p>Your project outline doesn’t have to be perfect. It can start as a jumbled list of ideas on what you think you have to do and learn.</p><p>A project is an experience anchor.</p><p>You now have somewhere to write ideas, knowledge, and techniques down to try.</p><p>When I wrote my book, my book outline made life meaningful. Almost every idea I came across could be added to the outline.</p><p>I felt like a child again. I became obsessed.</p><p>Everything was seen from a new lens. The lens of my project.</p><h3 id="_2-learn-as-you-build" tabindex="-1">2) Learn As You Build <a class="header-anchor" href="#_2-learn-as-you-build" aria-label="Permalink to &quot;2) Learn As You Build&quot;">​</a></h3><p>If you aren’t building, you aren’t learning.</p><p>If you aren’t actively applying what you learn to a problem sitting in your mind, you are simply stacking useless knowledge as soon-to-be-forgotten brain fog.</p><p>When you <em>start</em> building something, there are only a few things you need to know: the fundamentals.</p><p>You have no business researching advanced tactics yet.</p><p>The fundamentals will take you 80% of the way there (and for most people, that’s millions of dollars, a jacked physique, or a stress-free life).</p><p>New tactics will take you the next 20% of the way, but this mental bandwidth should be reserved for obsession, mastery, and your life’s work of a few specific skills and interests.</p><p>When you have a project to build, do one or both of the following:</p><ul><li>Purchase a beginner-level course on the topic</li><li>Watch overview videos on YouTube that teach the fundamentals</li></ul><p>Study them until you have clarity on what to do next. Then, do it, and when you encounter a problem:</p><ul><li>Refer back to sections of the course or video</li><li>Research how to solve that problem directly</li><li>Watch tutorials where people <em>build</em> projects similar to yours and see how they overcome those problems</li></ul><p>Learning is problem-solving, not hoarding as much knowledge as you can.</p><h3 id="_3-teach-what-you-learn" tabindex="-1">3) Teach What You Learn <a class="header-anchor" href="#_3-teach-what-you-learn" aria-label="Permalink to &quot;3) Teach What You Learn&quot;">​</a></h3><p><img src="'+n+'" alt=""></p><p>I, of course, recommend teaching in public by writing as a <a href="/letters/the-one-person-business-revisited-turn-yourself-into-a-business">personal brand</a> (or your public resume) so you can also attract high-paying opportunities as you learn. (This is what I teach in <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>).</p><ul><li>Write in public and let people criticize you.</li><li>Teach your friends to make for interesting conversations.</li><li>Take notes on the subject but write them as if you were teaching yourself.</li></ul><p>Teaching almost forces you to make sense of the information.</p><p>You have to structure it, explain it, and ensure that you aren’t giving false knowledge.</p><p>When I write these newsletters, I don’t know everything. But I can guarantee that writing for 4 years has accelerated my learning in the topics I love well beyond what I would’ve learned trapped in tutorial hell.</p><p>When you build a brand (not in the business sense, in the sense of your external display to the world), building and teaching collapse into your work.</p><p>Your life becomes a meaningful series of solving problems, learning how to solve them, teaching others, and making an income doing so. I believe this is what evolution has allowed: people doing what they love without barriers thanks to the internet.</p><p>On imposter syndrome:</p><p>Simple – be honest.</p><p>Don’t fabricate your experience. Don’t lie about what you know. Teach from the lens you learned it.</p><p>Something as simple and attention-grabbing as, <em>“I read The Art of Focus in 23 hours, here are the life-changing lessons I learned on joining the new rich,”</em> is honest to where you are in your learning journey.</p><p>Similar to marketing a product, simply don’t promise results you don’t have.</p><h3 id="_4-expand-into-a-new-level-of-mind" tabindex="-1">4) Expand Into A New Level Of Mind <a class="header-anchor" href="#_4-expand-into-a-new-level-of-mind" aria-label="Permalink to &quot;4) Expand Into A New Level Of Mind&quot;">​</a></h3><p><img src="'+i+'" alt=""></p><p>By this point, you may still feel overwhelmed or like you aren’t learning much.</p><p>This is a good thing.</p><p>Your mind is primed for pattern recognition.</p><p>So:</p><ul><li><strong>Launch yourself into the unknown</strong> – immerse yourself in the culture, environment, and information related to what you are trying to learn.</li><li><strong>Condition your mind through repetition and exposure</strong> – slowly understand the lingo, vocabulary, and skill set of those who have seen success in that topic.</li><li><strong>Let your mind expand through the discomfort</strong> – the worst thing you can do is quit when you are feeling growing pains.</li></ul><p>You aren’t seeing results because you aren’t the person who would see results.</p><p>This process allows you to become a new person by letting your old version die.</p><p>Like when you are adopting new habits, you have to get out of the old environment that fueled your bad habits.</p><p>To make this more practical:</p><ul><li><strong>Read books</strong> – books give you 10 years of effort from 6 hours of reading.</li><li><strong>Consume lectures</strong> – long articles and videos give you 3 days of effort in 20 minutes.</li><li><strong>Follow new people</strong> – this is less about consuming short-form content and more about training your mind to be in that tribe of people.</li></ul><p>Buy 3 books.</p><p>One best-seller, one technical, and one historical.</p><p>Burn through them and don’t let your obsession die.</p><p>This may seem like a long process, but we aren’t trying to learn something on a surface level, we are trying to become masters as fast as possible.</p><h3 id="_5-make-connections-to-solidify-understanding" tabindex="-1">5) Make Connections To Solidify Understanding <a class="header-anchor" href="#_5-make-connections-to-solidify-understanding" aria-label="Permalink to &quot;5) Make Connections To Solidify Understanding&quot;">​</a></h3><p>When you master one thing, it becomes easier to master others.</p><p>Principles are Universal. They overlap.</p><p>When you master fitness, you can master business in half the time, and then relationships in another half.</p><p>Most people never master one domain of their lives, so they never experience exponential personal growth.</p><p>When you feel like you have a solid understanding of the topic you are trying to learn:</p><ul><li><strong>Zoom out one layer</strong> – move from “Photoshop” to “graphic design” to “creative work.”</li><li><strong>Take note of signal</strong> – when your mind signals important information, write it down.</li><li><strong>Build better projects</strong> – from a new level of mind, build a new project that will take you to the success you want to see.</li></ul><p>In my own experience, my knowledge compounded when I peeled back a layer from web design to marketing to content creation to metaphysics.</p><p>This is also a great way to start your one-person business.</p><p>Start by learning, teaching, and building in one domain then branch out as your audience expands.</p><p>We help you do this and start your digital career in 90 days inside <a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex University</a>.</p><p>Now, go learn, build, and enjoy your weekend.</p><p>Dan</p>',145)])])}const v=r(u,[["render",p]]);export{b as __pageData,v as default};
